A="/tmp/claude-0/algos/bench/results"; B="/tmp/claude-0/algos/review/rerun/results"
out=[]
for what, claim, scr in listed:
    a=json.load(open(f"{A}/{scr}.json")); b={r["what"].strip(): r for r in json.load(open(f"{B}/{scr}.json"))}
    best=min(a, key=lambda r: abs(r["median_ms"]-claim)/claim)
    rb=b[best["what"].strip()]
    ratio=rb["median_ms"]/claim
    out.append(dict(what=what, claimed_ms=claim, measured_ms=round(rb["median_ms"],4), ok=bool(1/1.3<=ratio<=1.3), src=best["what"].strip()))
    print(f"{'OK ' if out[-1]['ok'] else 'BAD'} x{ratio:5.2f} {claim:>10} -> {rb['median_ms']:>11.4f}  {what[:60]}  [{best['what'].strip()[:50]}]")
json.dump(out, open("/tmp/claude-0/algos/review/side/listed.json","w"), indent=0)
print(sum(o['ok'] for o in out), "/", len(out))
